-- FASE D · Bloque 4 · Profetas menores 1: Oseas, Joel, Amós y Abdías
update public.biblical_sources
set provider_version = 'profetas-menores-v1-2026-08-02',
    content_hash = encode(extensions.digest('vida-contexto-editorial|profetas-menores-v1-2026-08-02', 'sha256'), 'hex'),
    metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('latest_batch','minor-prophets','generated_by_ai',false),
    updated_at = now()
where slug = 'vida-contexto-editorial';

update public.biblical_books
set metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('coverage_status','context_ready'), updated_at=now()
where code in ('HOS','JOL','AMO','OBA');

with source as (select id from public.biblical_sources where slug='vida-contexto-editorial'),
data(slug,book_code,scope_kind,chapter_start,chapter_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places) as (
values
('oseas-perfil','HOS','book',1,14,'Oseas: pacto, amor herido y retorno','Oseas anuncia juicio al reino del norte mediante metáforas familiares, denuncia idolatría y alianzas políticas y sostiene que el amor fiel de Dios continúa llamando a Israel al retorno.','El profeta habla en el siglo VIII a. C., durante inestabilidad dinástica, presión asiria y búsqueda de apoyo en Egipto y otras potencias antes de la caída de Samaria.','El lenguaje de pacto, conocimiento de Dios y hesed ocupa el centro. La relación conyugal funciona como metáfora profética de la relación entre Dios e Israel y recibió amplias lecturas rabínicas.','Acciones simbólicas de los capítulos iniciales dan paso a oráculos y recuerdos históricos. Padre, esposo, desierto, viña y rocío expresan juicio y restauración.','Confrontar una religión sin fidelidad ni justicia y mostrar que el propósito del juicio no es humillación final, sino verdad, sanidad y retorno.','El amor fiel no ignora el daño, pero tampoco reduce a la persona a su peor decisión. El arrepentimiento bíblico incluye volver, conocer y practicar misericordia.','Las metáforas matrimoniales no autorizan abuso, control o vergüenza sexual. Gomer no debe usarse como insulto contra mujeres reales ni el texto como justificación de permanecer en relaciones peligrosas.',ARRAY['Oseas','hesed','conocimiento de Dios','pacto','retorno','Samaria']::text[],ARRAY['israelitas del norte','asirios','egipcios']::text[],ARRAY['Samaria','Israel','Asiria','Egipto']::text[]),
('oseas-1-3-familia','HOS','section',1,3,'Familia simbólica y restauración del pacto','Los nombres de los hijos y la relación de Oseas funcionan como señales de ruptura, juicio y futura restauración, culminando en una búsqueda que expresa amor persistente.','Los nombres simbólicos eran recursos proféticos públicos. Jezreel recordaba violencia dinástica y la fragilidad del reino del norte.','Las fórmulas «no compadecida» y «no mi pueblo» son revertidas en promesas de pertenencia. La tradición ha debatido cuánto debe leerse como biografía y cuánto como acción simbólica.','Juicio y reversión se alternan; el desierto reaparece como lugar de renovación y una relación rota recibe lenguaje de nueva alianza.','Mostrar que las consecuencias son reales, pero la identidad del pueblo no queda reducida para siempre a rechazo y fracaso.','La restauración digna no encubre el daño. Requiere verdad, límites, responsabilidad y una decisión libre de volver.','La compra o recuperación del capítulo 3 pertenece a una economía antigua y no presenta a una persona como propiedad moderna. No debe imitarse literalmente ni romantizarse la desigualdad de poder.',ARRAY['Jezreel','Lo-ruhama','Lo-ammi','desierto','restauración']::text[],ARRAY['familia de Oseas','Israel']::text[],ARRAY['Jezreel','desierto']::text[]),
('oseas-4-11-acusacion','HOS','section',4,11,'Falta de conocimiento, alianzas e historia de amor','El profeta denuncia sacerdotes, gobernantes y pueblo por violencia, engaño, culto interesado y alianzas, mientras recuerda el éxodo y presenta a Dios como padre que enseñó a caminar a Efraín.','Israel combinaba prosperidad desigual, santuarios regionales y diplomacia entre Asiria y Egipto. La crisis no era solamente ritual, sino política y social.','«Mi pueblo perece por falta de conocimiento» se refiere al conocimiento de Dios expresado en pacto, justicia y enseñanza, no a información general o credenciales académicas.','Acusaciones judiciales, imágenes agrícolas y memoria parental se mueven desde dureza hacia una de las expresiones más intensas de compasión del libro.','Mostrar que ignorancia religiosa puede ser responsabilidad de líderes y sistemas, y que la compasión divina confronta sin abandonar.','Conocer a Dios implica una práctica de misericordia y verdad. La ternura no elimina justicia, pero impide que el juicio sea presentado como placer en destruir.','La frase sobre falta de conocimiento no debe usarse para culpar a personas con menor educación. Las imágenes de infidelidad no autorizan lenguaje degradante contra grupos o géneros.',ARRAY['conocimiento','sacerdotes','Efraín','alianzas','padre','compasión']::text[],ARRAY['israelitas','sacerdotes','gobernantes','asirios','egipcios']::text[],ARRAY['Efraín','Betel','Asiria','Egipto']::text[]),
('oseas-12-14-retorno','HOS','section',12,14,'Memoria de Jacob y llamado final al retorno','Oseas relee a Jacob y el éxodo, denuncia balanzas engañosas y autosuficiencia y termina invitando a Israel a volver con palabras y recibir sanidad y vida.','El comercio, la riqueza y la presión imperial aparecen junto con memorias ancestrales. La caída política se interpreta como resultado de una larga pérdida de fidelidad.','El retorno final no depende de sacrificios costosos, sino de confesión, abandono de alianzas y reconocimiento de que la misericordia se encuentra en Dios.','Una disputa con el antepasado Jacob conduce a oráculos de caída y luego a un poema de sanidad con rocío, lirio, olivo y raíces.','Concluir que la restauración requiere abandonar engaño y seguridad falsa, y que el último movimiento de Dios es sanar la infidelidad.','Volver puede comenzar con palabras honestas y una renuncia a aquello que sustituye a Dios. La sanidad espiritual se expresa como nueva capacidad de florecer.','Las imágenes de sanidad no prometen curación física automática. El cierre sapiencial reconoce que los caminos de Dios pueden ser recorridos o rechazados y no autoriza desprecio hacia quien todavía lucha.',ARRAY['Jacob','balanzas','retorno','palabras','sanidad','rocío']::text[],ARRAY['Israel','comerciantes','gobernantes']::text[],ARRAY['Efraín','Asiria']::text[]),
('joel-perfil','JOL','book',1,3,'Joel: crisis, día de YHWH y derramamiento del Espíritu','Joel interpreta una devastación agrícola como llamado comunitario al retorno, desarrolla el tema del día de YHWH y anuncia restauración, Espíritu derramado y justicia para las naciones.','La fecha del libro es debatida. La ausencia de un rey y la importancia de sacerdotes y templo permiten propuestas desde periodos monárquicos tardíos hasta postexílicos.','El ayuno comunitario, el toque de shofar y la asamblea solemne pertenecen a prácticas de arrepentimiento. La promesa del Espíritu sobre toda carne amplía la participación profética.','La descripción de una plaga se transforma en lenguaje militar y cósmico. Un centro litúrgico de retorno abre hacia promesa, Espíritu y juicio internacional.','Convocar a una respuesta comunitaria que involucre corazón y práctica, y afirmar que la renovación no queda limitada por edad, género o posición social.','Una crisis puede llevar a examinar hábitos y solidaridades sin afirmar que cada desastre natural es castigo identificable. El Espíritu capacita a una comunidad diversa.','La plaga no debe usarse para declarar juicio divino sobre víctimas de desastres actuales. El día de YHWH no ofrece un calendario y las imágenes cósmicas son lenguaje profético, no pronóstico astronómico.',ARRAY['langosta','día de YHWH','ayuno','retorno','Espíritu','Sion']::text[],ARRAY['Judá','sacerdotes','ancianos','jóvenes','naciones']::text[],ARRAY['Jerusalén','Sion','valle de Josafat']::text[]),
('joel-1-2-crisis-retorno','JOL','section',1,2,'Devastación, asamblea y promesa de restauración','Una crisis agrícola sin precedentes afecta alimento y culto; el profeta convoca a toda la comunidad, insiste en rasgar el corazón y anuncia compasión, lluvia y recuperación.','Una invasión de langostas podía destruir cosechas, economía y ofrendas. La supervivencia dependía de lluvias estacionales y cooperación comunitaria.','El llamado incluye niños, ancianos, recién casados, sacerdotes y pueblo. La fórmula sobre Dios compasivo retoma la revelación de Éxodo 34.','Lamento agrícola, alarma militar, liturgia de retorno y respuesta divina forman una secuencia desde pérdida hacia restitución.','Enseñar que el arrepentimiento no es espectáculo externo y que la respuesta a una crisis debe incluir a toda la comunidad.','La compasión divina no elimina el proceso, pero permite reconstruir sin que la vergüenza tenga la última palabra.','«Restituiré los años» no promete recuperar exactamente cada oportunidad perdida ni riqueza multiplicada. Debe leerse como restauración comunitaria después de una crisis concreta.',ARRAY['langosta','cosecha','asamblea','corazón','compasión','restauración']::text[],ARRAY['campesinos','sacerdotes','familias','Judá']::text[],ARRAY['Jerusalén','Sion']::text[]),
('joel-2-3-espiritu-naciones','JOL','section',2,3,'Espíritu sobre toda carne y justicia entre naciones','La promesa se expande hacia el derramamiento del Espíritu sobre hijos, hijas, ancianos, jóvenes y servidores, y luego hacia una escena de juicio por violencia y explotación de pueblos.','La venta de personas, desplazamiento y guerra formaban parte de conflictos regionales. El lenguaje del valle reúne memoria histórica y expectativa escatológica.','La promesa del Espíritu fue importante en interpretaciones judías de los últimos tiempos y fue retomada en Hechos 2 dentro de la experiencia cristiana.','Inclusión profética y símbolos cósmicos conducen a oráculos contra naciones y a una imagen final de abundancia y presencia en Sion.','Afirmar que el Espíritu atraviesa jerarquías sociales y que la esperanza espiritual incluye justicia frente a trata, saqueo y violencia.','La acción de Dios puede dar voz a personas que sistemas religiosos dejaron en segundo plano. La espiritualidad no se separa del valor de vidas explotadas.','«Toda carne» no debe restringirse arbitrariamente por género o clase. Las naciones nombradas son antiguas y no deben identificarse directamente con estados actuales.',ARRAY['Espíritu','hijos e hijas','profecía','naciones','justicia','Sion']::text[],ARRAY['jóvenes','ancianos','servidores','Judá','naciones']::text[],ARRAY['Jerusalén','Sion','valle de Josafat']::text[]),
('amos-perfil','AMO','book',1,9,'Amós: justicia, culto y responsabilidad del privilegio','Amós, pastor y cultivador del sur, profetiza contra el reino del norte por violencia internacional, lujo construido sobre explotación, tribunales corruptos y culto separado de justicia.','El ministerio se ubica durante prosperidad del siglo VIII a. C. bajo Jeroboam II, antes del avance asirio. La riqueza creció junto con concentración de tierras y desigualdad.','Amós insiste en que la elección de Israel aumenta responsabilidad. Sus palabras sobre justicia y rectitud son centrales en ética judía y profética.','Oráculos contra naciones rodean a Israel, seguidos por discursos, ayes, visiones y un conflicto con Amasías en Betel. Una breve promesa de restauración cierra el libro.','Desmontar la idea de que culto, identidad elegida o prosperidad prueban aprobación divina cuando la sociedad oprime al pobre.','La adoración creíble escucha el clamor del vulnerable y transforma economía, tribunales y liderazgo. El privilegio espiritual implica mayor responsabilidad.','Amós no enseña que toda riqueza individual sea pecado, sino que condena lujo sostenido por explotación. Sus juicios no autorizan desprecio contra pueblos actuales.',ARRAY['Amós','justicia','pobre','Betel','culto','día de YHWH','responsabilidad']::text[],ARRAY['israelitas del norte','judíos','pobres','ricos','sacerdotes']::text[],ARRAY['Tecoa','Betel','Samaria']::text[]),
('amos-1-2-naciones-israel','AMO','section',1,2,'Círculo de acusaciones y responsabilidad de Israel','El profeta denuncia violencia de naciones vecinas y luego dirige la acusación hacia Judá e Israel por vender al justo, explotar al pobre y profanar relaciones y culto.','Los oráculos recuerdan guerras, trata, deportaciones y atrocidades regionales. El público israelita termina incluido en la misma evaluación que esperaba contra otros.','La elección y el éxodo no eximen de justicia. La memoria de liberación hace más grave reproducir opresión contra personas vulnerables.','La fórmula repetida «por tres y por cuatro» crea un círculo que se cierra sobre los oyentes, desplazando atención del enemigo externo al propio sistema.','Enseñar que condenar injusticias ajenas no sustituye examinar las propias y que la memoria de haber sido liberado debe producir protección de otros.','La autocrítica forma parte de la fidelidad. Una comunidad no pierde identidad por reconocer daño; puede recuperarla mediante justicia.','Las naciones antiguas no deben usarse como equivalencias geopolíticas actuales. La venta del pobre exige atención ética y no debe espiritualizarse hasta perder su dimensión económica.',ARRAY['naciones','violencia','pobre','venta','éxodo','responsabilidad']::text[],ARRAY['arameos','filisteos','fenicios','edomitas','amonitas','moabitas','Israel']::text[],ARRAY['Damasco','Gaza','Tiro','Edom','Amón','Moab','Betel']::text[]),
('amos-3-6-culto-injusticia','AMO','section',3,6,'Lujo, tribunales y culto rechazado','Amós anuncia que el privilegio de conocer a Dios trae evaluación, denuncia casas lujosas, opresión, tribunales corruptos y fiestas religiosas que no producen justicia.','Samaria contenía una élite urbana con casas decoradas y acceso a comercio mientras campesinos perdían tierra y voz legal.','El rechazo de cantos y sacrificios no es rechazo permanente de adoración, sino denuncia de culto que convive con abuso. El llamado a que justicia corra como agua se vuelve centro del mensaje.','Preguntas retóricas, lamentos, sarcasmo y ayes enfrentan seguridad, comodidad y una falsa expectativa del día de YHWH.','Mostrar que una liturgia puede ser técnicamente correcta y moralmente inaceptable si no se relaciona con justicia estructural.','La espiritualidad se escucha en canciones, pero también en salarios, tribunales, trato al pobre y uso del poder.','«Ay de los reposados» no condena descanso saludable, sino indiferencia privilegiada frente al daño. La frase sobre música no debe usarse para despreciar estilos musicales modernos.',ARRAY['Samaria','lujo','tribunales','culto','justicia como río','día de YHWH']::text[],ARRAY['ricos','pobres','jueces','adoradores']::text[],ARRAY['Samaria','Betel','Gilgal']::text[]),
('amos-7-9-visiones-restauracion','AMO','section',7,9,'Visiones, conflicto en Betel y restauración final','Amós contempla langostas, fuego, plomada y fruto maduro, es expulsado por el sacerdote Amasías y anuncia el fin del santuario real antes de una promesa de restauración.','Betel funcionaba como santuario vinculado a la monarquía. Criticarlo era también desafiar legitimidad política y economía religiosa.','Amós rechaza ser reducido a profeta profesional y apela a un llamado recibido mientras trabajaba. El cierre sobre la cabaña de David fue interpretado de diversas maneras.','Visiones progresan desde intercesión hacia certeza de juicio; un relato biográfico muestra el costo público del mensaje y un epílogo abre esperanza.','Afirmar que instituciones religiosas pueden proteger intereses del poder y que la restauración verdadera necesita atravesar la verdad del juicio.','Una vocación no depende de pertenecer a una élite profesional. La fidelidad puede requerir hablar fuera del lugar de origen sin buscar prestigio.','La plomada no debe convertirse en técnica adivinatoria. Amós 9 no justifica proyectos nacionalistas ni promete riqueza agrícola automática a individuos.',ARRAY['plomada','Amasías','Betel','llamado','fin','cabaña de David']::text[],ARRAY['profetas','sacerdotes','Israel','Judá']::text[],ARRAY['Betel','Tecoa','Samaria']::text[]),
('abdias-perfil','OBA','book',1,1,'Abdías: Edom, violencia y el día de YHWH','Abdías condena a Edom por orgullo y por aprovechar la caída de Jerusalén, y anuncia que la violencia regresará sobre quienes participaron en saqueo y entrega de fugitivos.','Judá y Edom compartían memoria ancestral y una frontera conflictiva. El oráculo probablemente responde a la destrucción de Jerusalén y a la colaboración o aprovechamiento edomita.','Edom se asocia con Esaú, hermano de Jacob, de modo que su violencia se presenta también como traición entre parientes. La tradición conserva dolor por esa ruptura.','El libro breve se mueve desde orgullo en fortalezas hacia acusaciones por observar, saquear y entregar, y termina ampliando el día de YHWH a todas las naciones.','Denunciar la neutralidad que se beneficia del sufrimiento ajeno y afirmar que ninguna seguridad geográfica o política vuelve impune la violencia.','No participar directamente no elimina responsabilidad cuando alguien celebra, saquea o bloquea refugio para personas perseguidas.','Edom antiguo no equivale a un pueblo o país moderno. El libro no autoriza odio étnico ni venganza; su lenguaje de retribución debe leerse como denuncia profética de violencia.',ARRAY['Abdías','Edom','Esaú','Jerusalén','orgullo','violencia','fugitivos']::text[],ARRAY['edomitas','judíos','naciones']::text[],ARRAY['Edom','Jerusalén','monte Sion']::text[]),
('abdias-1-21-juicio-restauracion','OBA','section',1,1,'Orgullo de Edom y restauración de Sion','El único capítulo acusa a Edom de confiar en sus alturas, permanecer al margen durante la calamidad de Judá y participar en saqueo y entrega, antes de anunciar restauración para Sion.','Las fortalezas montañosas de Edom ofrecían protección y rutas comerciales. La caída de Jerusalén creó oportunidades para ocupar territorio y capturar refugiados.','La memoria de Jacob y Esaú intensifica la acusación: una relación fraterna fue sustituida por oportunismo y enemistad.','Una serie de prohibiciones retrospectivas «no debiste» enumera la progresión desde mirar hasta participar, seguida por una inversión de destino.','Mostrar cómo la complicidad crece por etapas y llamar a reconocer responsabilidad antes de que observar se convierta en colaboración.','Proteger a quien huye y rechazar beneficio obtenido del desastre ajeno son expresiones concretas de justicia.','La restauración territorial es poesía profética de una comunidad herida y no debe utilizarse como mapa jurídico directo para disputas actuales.',ARRAY['orgullo','complicidad','saqueo','fugitivos','Sion','restauración']::text[],ARRAY['edomitas','judíos','refugiados']::text[],ARRAY['Edom','Jerusalén','Sion']::text[])
)
insert into public.biblical_context_units(slug,book_code,source_id,scope_kind,chapter_start,verse_start,chapter_end,verse_end,title,summary,historical_context,jewish_context,literary_context,authorial_intent,theological_reflection,interpretive_cautions,key_terms,people_groups,places,source_locator,provider_version,content_hash,review_status,enabled,metadata)
select data.slug,data.book_code,source.id,data.scope_kind,data.chapter_start,NULL,data.chapter_end,NULL,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions,data.key_terms,data.people_groups,data.places,'vida://corpus/contexto/profetas-menores/v1#'||data.slug,'profetas-menores-v1-2026-08-02',encode(extensions.digest(concat_ws('|',data.slug,data.title,data.summary,data.historical_context,data.jewish_context,data.literary_context,data.authorial_intent,data.theological_reflection,data.interpretive_cautions),'sha256'),'hex'),'approved',true,jsonb_build_object('coverage_batch','minor-prophets','generated_by_ai',false,'review_level','editorial')
from data cross join source
on conflict(slug) do update set book_code=excluded.book_code,source_id=excluded.source_id,scope_kind=excluded.scope_kind,chapter_start=excluded.chapter_start,chapter_end=excluded.chapter_end,title=excluded.title,summary=excluded.summary,historical_context=excluded.historical_context,jewish_context=excluded.jewish_context,literary_context=excluded.literary_context,authorial_intent=excluded.authorial_intent,theological_reflection=excluded.theological_reflection,interpretive_cautions=excluded.interpretive_cautions,key_terms=excluded.key_terms,people_groups=excluded.people_groups,places=excluded.places,source_locator=excluded.source_locator,provider_version=excluded.provider_version,content_hash=excluded.content_hash,review_status='approved',enabled=true,metadata=excluded.metadata,updated_at=now();